from pathlib import Path
import numpy as np
import scipy.io as sio
import pickle, json
root = Path('data')
for p in sorted(root.rglob('*')):
    if not p.is_file():
        continue
    suf = p.suffix.lower()
    print('\n===', p, '===')
    try:
        if suf == '.npy':
            arr = np.load(p, allow_pickle=True)
            print('npy type=', type(arr), 'shape=', getattr(arr, 'shape', None), 'dtype=', getattr(arr, 'dtype', None))
            if getattr(arr, 'dtype', None) == object:
                print('object repr=', repr(arr)[:500])
        elif suf == '.npz':
            z = np.load(p, allow_pickle=True)
            print('npz keys=', list(z.keys()))
            for k in z.keys():
                a = z[k]
                print(' ', k, type(a), getattr(a, 'shape', None), getattr(a, 'dtype', None))
        elif suf == '.mat':
            m = sio.loadmat(p, simplify_cells=True)
            print('mat keys=', [k for k in m.keys() if not k.startswith('__')])
            for k,v in m.items():
                if k.startswith('__'): continue
                print(' ', k, type(v), getattr(v, 'shape', None))
        elif suf in {'.pkl', '.pickle'}:
            obj = pickle.load(open(p,'rb'))
            print('pickle type=', type(obj))
            if isinstance(obj, dict):
                print('dict keys=', list(obj.keys())[:50])
        elif suf in {'.csv', '.tsv', '.txt'}:
            print(p.read_text(errors='ignore')[:1000])
        else:
            print('skipping detailed parse')
    except Exception as e:
        print('ERROR', type(e).__name__, e)
